import React, { useEffect, useState } from 'react';
import api from '../services/api';

const Promociones = () => {
  const [promos, setPromos] = useState([]);

  useEffect(() => {
    api.get('/promociones')
      .then(response => setPromos(response.data))
      .catch(error => console.error("Error cargando promociones:", error));
  }, []);

  return (
    <div className="table-container">
      <h3>Lista de Promociones</h3>
      <table className="admin-table">
        <thead>
          <tr><th>ID</th><th>Título</th><th>Descuento</th></tr>
        </thead>
        <tbody>
          {promos.map(p => (
            <tr key={p.id}><td>{p.id}</td><td>{p.titulo}</td><td>{p.descuento}%</td></tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};
export default Promociones;
